// Build the apology / disregard email for a revoked approval.
const b = $input.item.json.body || $input.item.json;
if (!b.agentEmail) throw new Error('agentEmail is required');
if (!b.conversationId) throw new Error('conversationId is required');

const agent = b.agent || 'Agent';
const contact = b.contact || 'the customer';
const date = b.date || '';
const conversationId = b.conversationId;

let finalEmailBody = String(b.finalEmailBody || '').trim();
if (!finalEmailBody) {
  const apology =
    b.apologyNote ||
    `Please disregard the quality feedback email regarding your interaction with ${contact}${date ? ` on ${date}` : ''}. That score was approved in error and has been removed from the system. Your performance numbers have been updated. We apologize for any confusion.`;
  const scoreLine =
    b.revokedScore != null ? `\n\nThe incorrect score (${b.revokedScore}/100) no longer appears on your record.` : '';
  finalEmailBody = `Dear ${agent},\n\n${apology}${scoreLine}\n\nConversation reference: ${conversationId}\nCustomer: ${contact}\nCustomer Phone Number: ${b.phone || 'N/A'}\nDate: ${date || 'N/A'}\n\nBest regards,\nQA Team`;
}

return {
  json: {
    agent,
    agentEmail: b.agentEmail,
    conversationId,
    contact,
    phone: b.phone || '',
    date,
    revokedScore: b.revokedScore ?? null,
    revokedBy: b.revokedBy || '',
    feedbackType: 'revocation',
    emailSubject: 'Please disregard - quality feedback sent in error',
    finalEmailBody,
    idempotencyKey: `revocation:${conversationId}`,
    receivedAt: new Date().toISOString(),
  },
};
